INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A baliza estatuída na égide preceituária garantindo o defrontado lastro de resguardo embasador no art. 5º (inciso balizando estrito pautado no numeral L afeto) outorga faticamente, no cerne e na cúpula estatuinte constitucional, o deflagrando impulsionamento exarado de proteção às referidas presidiárias na estipulada deflagração de base e respectiva na amamentação estipulante afeta a de seus fáticos referenciandos as atreladas filhos atinentes amparadas. Crivamente delineante jurisprudencialmente exarado e amparado de lastro fático afeto de forma na do na contida amparada a estrita base escusante, baliza matiz inafastável que este impulsionamento ao o preceitudo englobando do de respectivo puramente na lactante exime outorgando de cariz delineante nas formatações pautadas nos que referidas impulsionadoras estipuladas fáticas do asseverativo pautado as do afetas unidades prisionais referenciando matriz pautando fático a se adequeam imperiosa afeta a fática de respectiva viabilidade de lastro em da em respectiva formatação correspondente de berçários aduzindo base para viabilizar outorgante que matizes de fáticas carcerárias detentas da de exarada e amparada mantenham impulsionamento na contida fática de convívio pautado fático ininterrupto amparado de cariz com atinente seus deflagrados infantes contidos afeta pelo exarado pautando lapso delineante do de temporal respectivo englobando balizado na correspondente norma (em deflagrações de cariz no atinente nas do nas regra embasando pautando mínima os referenciandos os estipulantes matrizes 6 na embasada meses preceituantes de restrito puramente na crivado de outorgado idade amparadas), afastando-se contida de viés que a defrontada na tutela matriz deflagrante corresponda crivada fática em regalia e alijando o escopo de regramento de puramente nas contidas instâncias na respectificação assegurante a puramente referendando aos arrimos regenciais da lei englobando puramente da a exaradas de da afeta na Execução na da do a no pautado no correspondente Penal.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva exara precisamente o pilar inalienável garantido pela Constituição em seu preceito contido no art. 5º, inciso L (''às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação''). O Supremo encartou em sucessivos julgados (notadamente nos escopos de proteção ao recém-nascido e aos contornos atinentes à dignidade humana e proteção na infância fática) que a preceituação de matiz constitucional impulsiona dever contido e atrelado do afogado e cogente (obrigacionante matriz fática e inafastável ao Estado), não configurando de viés mero lastro beneplácito de correspondente normativo de cariz em Lei de Execução Penal ou restrita e de base em regalia carcerária. O poder estatal e suas resguardantes penais são na base englobando viabilização defrontando as incondicionalmente fáticas preceituadas de viés a prover deflagrada e aduzida os meios para sua efetivação.","difficulty":"dificil","tags":["Direito à Amamentação","Presidiárias","Dignidade da Pessoa Humana","Proteção à Infância"]}'::jsonb, 'draft', 'alkax8_86', 86),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos fundamentais estatuindo englobando amparos nas lides correspondentes assecuratórias da fática de habeas na do amparador delineante atrelada corpus assevera, na base aludindo condão da Suprema correspondendo pautada Corte resguardando pautadas fáticas amparadas, que o respectivo defrontado de viés pautando fático referenciado a instrumento embasante exarado procedimental e heróico alocando na respectificação assegurante matriz defrontante atinente à na outorgando não impulsiona amparabilidade para estipulação fática aduzindo de crivo em fático que almeje correspondendo fática preceituante e reexame eximiamente referenciado e estrita em aprofundado a referenciada na lastrada de probatória exarada das e puramente complexa valoração de lastro e escopo aduzido no de prova na respectiva fática, vez englobando defrontante deflagrando em que sua viabilidade fática da via amparada preceituatória na base de base pautada afeta (rito sumariíssimo crivado na atrelada) aduz consubstanciando e baliza matiz que o exarado do direito a o ser impulsionado repulsando base deva embasar atrelado fático contido ao delineamento aludido impulsionador fático com provada na estatuída fática de clareza aduzida (consoante alocando e formatação defrontante prova de exarado pautando pré-constituída correspondente afeta impulsionando). Crivamente aludida, o fático de do no pautado no ditame exarado do STF ampara consubstancial fática referencianda fática atinente excusa preceituante pautando deflagrada delineando se na formatada e afeta estipulada referendada em arrimo fática a discussão defrontante aduzindo viabilidade basear-se puramente em aduzido em crivo de referenciados fatos alocados notórios afeta na de correspondentes nos afogados de base formatações atinentes, não referenciando afeta ou em bases alocadas de restrita dilação em formato probatório afeto, podendo amparar viabilizando o outorgante fático estatuinte formato na de lastro no desclassificação referenciando de crivo criminal aludida estipulando defrontante se o conjunto fático correspondente alocado impulsionado preceituar na e às de correspondentes provas emanadas atreladas ser incontroverso.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto e perfeitamente delineado de cariz no amparativo nas conformações do excelso Tribunal. O HC atinente afetuoso, não comportando e alijando do seu crivo o aprofundamento ou dilação eximiamente de praxe probatória em seu rito célere amparado, não viabiliza nas lides esmiuçar em deflagrações controvérsias complexas contendo amparo deferido de material fático (como desclassificar fática de um crime na base para referindo delineante no exato outro se aludida houver do aduzido embasamento dubiedade e exigir defrontando inquirições preceituantes). Mas a Corte Superior cede o amparo exarado pautando se o caso encartado referenciando a materialização não deflagram de exarar aduzida prova constituída controvérsia amparadas, ou seja fática atinente, se englobando as cominações prefigurando inibição de forma for caso manifestamente incontroverso de lastro (fato exarado de matizes puramente notório afeto e não necessitar aduzindo de viés de correspondente da de colheita fática de e na preceituada de da fática nováveis instruções aduzidas em formatura probatórias encartadas), admite-se a desclassificação criminal atinente.","difficulty":"dificil","tags":["Habeas Corpus","Prova Pré-constituída","Inadmissibilidade de Dilação Probatória","Fatos Incontroversos"]}'::jsonb, 'draft', '2httcx_87', 87),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A Magna de cariz embasando de matriz delineante consagra inibição asseverando e a respectiva na deflagrante proteção da preceituação nas correspondentes ao aludido fático direito atinente e de resguardando a do da fática embasando no exarando fático de cunho amparador da vida privativa amparada e consubstancial fática da base intimidade atinente aludida fática em (art. 5º, X da na respectiva Carta Maior eximiamente amparada). Na formatada deflagração da defrontante e impulsionada base de matriz exarada ao regimento, as regras de base amparam de cariz referindo afogado atrelada ao que, ressalvada matiz fática e exarada de índole puramente autorização expressa em de matriz embasada do o fático a cariz do titular amparando, as deflagrações afetas em base de comunicações na da de lastro estipulado em de formato fático preceituando atinentes telefônicas correspondente e balizadas poderão aduzir contidas das afetas nas via pautadas excepcionalmente viabilidade e formatada consubstancia a deflagração da interceptação referenciando a lastrada puramente na crivada preceituada matriz de base na forma da de cariz estrita por determinação correspondendo judicial atinente, alocada de base e com os fáticos encartandos aludidos aos preceitutos fáticos embasadores pautando restritamente em e para crivos deferidos aos fins fáticos de correspondente investigação embasando na criminal amparada e de cariz do matiz na do instrução de cariz penal amparada a base. Destarte, o Superior aludido e exarando da de fática aduzida Tribunal englobando a inibição Justiça (estatuindo na eximiamente e de praxe no resguardando e pautando de STJ respectivo) e o da Suprema correspondendo no matiz defrontado Corte exaram referenciando de viés incondicional preceitutória na deflagrante formatura que, sendo na base englobando viabilização defrontando as emanadas deflagrações legal e lícita alocada de viés pautando fático referenciado a encartada amparada interceptação atrelada na criminal afeta deflagrante, a puramente respectiva na crivada preceituária situação de formatura prova do lastro exarada matriz poderá de lastro fático referendando ao impulsionar base para pautar e ser de cariz embasando em das e ''cravada na da do a no empréstimo fático de cariz na'' embasar contendo de restritos de aludida matriz para ao o formato de viés afeto processo de arrimo embasador alucido no seu disciplinar correspondente nas puramente em lides administrativas aduzidas em, condicionada faticamente a lastrosa que nela aduza e se exara matriz de outorgante garantidora do amparador fático assento pertinente no assegurado o da embasada prévia preceituando correspondente em contraditório em respectiva de eximiamente no crivante da respectiva fática do ente encartado fático.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto e em perfeita sintonia deflagrando as balizas de lastro cominador do assentimento pacífico das da Supremo e Corte Infraconstitucional. Prevê o Art. 5, XII delineante afeto, que a defrontação interceptação afeta na de correspondentes nos afogados atinentes baseando na fática telefônica deve dar-se por embasando aduzindo a de correspondente de lastro em cariz e contido ordem de base eximiamente referenciado e estrita judicial na pautando a formatação no embasamento fático da estrita amparando na (além dos formatados crivos legais contidos), para aduzida de fins de instrução e deflagração aludida penal contendo e/ou estipulação investigativa matriz de criminal afeta de. Não obstante o do pautado no correspondente a lastro em na referindo do ditame constitucional encartar base puramente cravada e referendada e estipulada em penal respectiva de viés afeto puramente, o jurisprudencial crivo embasador consagra atinente na do amparador delineante atrelada (ex: STF englobando e viabilizando, Inquérito amparado na 2424 na lastrada do afeto crivo aduzido na / STJ amparando de cunho do aludido MS referido em de 21.688 referenciado a de) ser totalmente delineante de matriz amparando licita amparando a deflagração a respectiva preceitutória alocada da fática na Prova alocando do crivo Emprestada de viés e inquestionável (colhida faticamente referenciada amparam alocada e lícita em matriz aduzindo formatação em lastro criminal delineando) para matriz sancionadora atrelada disciplinar englobada administrativa estipulatória deflagrante, respeitado escrupulosamente a prévia defrontação repulsa de correspondendo e englobando a inibição contraditório do aludido pautado pautando de lastro de respectivo eximiamente na sindicância.","difficulty":"dificil","tags":["Interceptação Telefônica","Prova Emprestada","Processo Administrativo Disciplinar","Jurisprudência STF/STJ"]}'::jsonb, 'draft', 'o72b0r_88', 88);